pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, type(uint120).max);

        // actor deposits Ether via fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // record state before withdraw
        uint256 balBefore = c.balances(actor);
        uint256 contractBalBefore = address(c).balance;

        // withdraw as actor
        vm.prank(actor);
        c.withdraw();

        uint256 balAfter = c.balances(actor);
        uint256 contractBalAfter = address(c).balance;

        // Invariant: total user balances (sum of everything in mapping) after withdraw equals
        // total user balances before withdraw minus amount withdrawn.
        // Since only caller's balance changes, this simplifies to:
        // balances[actor] decreased by amount, contract balance decreased by same amount.
        // Full invariant: (totalBalances_before - totalBalances_after) == (contractBalance_before - contractBalance_after)
        // Here totalBalances only involves actor, so:
        // balances[actor]_before - balances[actor]_after == contractBalance_before - contractBalance_after
        uint256 deltaBal = balBefore - balAfter;
        uint256 deltaEth = contractBalBefore - contractBalAfter;
        assertTrue(deltaBal == deltaEth);
    }
}

