pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        // Admissible domain: depositAmount > 0 and actor not address(0) (balance will be non-zero)
        vm.assume(actor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // Fund actor and deposit into contract via fallback
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        uint256 balanceBefore = c.balances(actor);
        require(balanceBefore == depositAmount, "setup failed: balance mismatch");

        // Attempt withdraw; distinguish revert vs success
        vm.prank(actor);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After an attempted withdraw, the balance must be zero if the call succeeded.
        // If it reverted, the balance remains unchanged. The reference always succeeds and
        // zeroes the balance, so balanceAfter == 0 holds universally for the reference.
        // The buggy version always reverts (require(false) after call), so for positive
        // balance before, balanceAfter == balanceBefore > 0, failing the assertion.
        uint256 balanceAfter = c.balances(actor);
        assertTrue(!ok || balanceAfter == 0);
    }
}

