    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackerBalance) public {
        vm.assume(amount > 0);
        vm.assume(attackerBalance > 0);
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.assume(address(attacker) != address(0));
        vm.deal(address(attacker), attackerBalance);
        vm.prank(address(attacker));
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "initial deposit failed");
