pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint96 depositAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);

        // Get total balances sum before any withdrawal
        uint256 sumBefore = _sumAllBalances();

        // Deposit via fallback
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        // Withdraw
        vm.prank(actor);
        c.withdraw();

        // Get sum of all balances after withdrawal
        uint256 sumAfter = _sumAllBalances();
        // ETH balance of C after withdrawal
        uint256 ethBalanceAfter = address(c).balance;

        // Invariant: sum of all balances == c's ETH balance (since total deposited = sum of balances = c's ETH balance + total withdrawn)
        // More precisely: after each withdrawal, sum of all balances must equal the ETH still held in C.
        // This holds for reference but fails for mutant (which sets balance to 1, leaving nonzero balances with zero ETH).
        assertTrue(sumAfter == ethBalanceAfter);
    }

    // Helper: returns sum of balances for the two known actors. The fuzzer supplies one actor,
    // so we only sum balances[actor] since no other deposits occur.
    function _sumAllBalances() internal view returns (uint256 total) {
        // We only need to consider the fuzzed actor; the invariant holds globally.
        total = c.balances(address(0x1)); // never used, but ensures we call public getter
        // We'll sum over available actors that could have non-zero balance. Since only actor receives deposits,
        // we can compute sum as:
        return c.balances(msg.sender) + c.balances(address(0)); // address(0) always 0.
    }
}

