    function testFuzz_property(uint256 amount, uint8 preFundRatio) public {
        // amount > 0 to have a non-zero balance before withdraw
        vm.assume(amount > 0);
        // preFundRatio: if >= 128, use the adversarial reverter as the caller;
        // otherwise, use a random EOA (to keep the domain wide).
        // This ensures the fuzzer explores both failing and succeeding scenarios.
        address caller;
        if (preFundRatio >= 128) {
            caller = address(new Reverter());
        } else {
