        vm.prank(caller);
        // deposit: fallback is payable, so send ether to get balance
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "deposit failed");

        // record balance before withdraw
        uint256 balanceBefore = c.balances(caller);

        vm.prank(caller);
        try c.withdraw() { } catch { }

        // After a failed withdraw, balance must be unchanged, meaning it's still >0.
        // The mutant erroneously clears it, breaking this invariant.
        // If the caller is a Reverter, withdraw will fail, and balance should remain >0.
        // If the caller is an EOA, withdraw may succeed; in that case the invariant still holds
        // (balanceBefore == 0 or >0, but after success it's 0, so >0 is not guaranteed).
        // To make the assertion universal, we only require that if before >0 and withdraw fails,
        // then after >0. We capture this by checking that if after == 0, then the call must have succeeded
