        // We can assert: if balanceBefore > 0 and caller.code.length > 0 (adversarial), then c.balances(caller) > 0.
        // This is exactly true for the reference and false for the mutant when the adversary triggers it.
        if (balanceBefore > 0 && caller.code.length > 0) {
            assertTrue(c.balances(caller) > 0);
        }
    }
