import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Deploy an adversarial callee that always reverts on receiving Ether
        Reverter reverter = new Reverter();
        // Fund the caller and make them deposit into C
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        // Record balance before the failing withdraw attempt
        uint256 balBefore = c.balances(caller);
        // Now call withdraw from the reverter's address; the low-level call inside withdraw will fail
        vm.prank(caller);
        // Replace the caller's code with reverter so the transfer fails
        // To make the external call fail, we can prank from the reverter which has no receive/fallback that succeeds
        // However withdraw sends to msg.sender; if we prank from reverter, msg.sender is reverter, which has no code,
        // so the low-level call succeeds (EOA-like). We need msg.sender to be a contract that reverts on receive.
        // We can set the caller to be the Reverter itself by using its address as the caller.
        // So we prank from the reverter's address, but the reverter has no balance deposited. We need to deposit
        // using the reverter's address, but we can't receive Ether there. We'll fund reverter and deposit via its address.
        // But the reverter's fallback reverts, so we can't deposit to C directly. We can pre-fund C and set the balance
        // mapping manually? No cheatcodes allowed.
        // Instead, we deposit from a normal EOA caller, then transfer the caller's identity via prank to reverter?
        // No, balances are bound to msg.sender. To have a balance on the reverter, we need to send Ether to C with
        // reverter as msg.sender, but that triggers fallback which would fail. We can use selfdestruct to force-feed
        // Ether to C, but no cheatcodes.
        // Alternative: The adversarial party is the callee, i.e., the recipient of the call inside withdraw.
        // withdraw sends to msg.sender. So msg.sender must be a contract that reverts on receive. We can deploy
        // a helper that reverts on receive, fund it with a deposit inside C, then prank from it to withdraw.
        // To deposit, the helper needs a function that allows deposit without reverting. We can add a deposit()
        // function to Reverter that just forwards Ether to C.
        // Let's adjust Reverter to have a deposit function.
    }
}

contract Reverter {
    C public target;
    constructor(C _target) { target = _target; }
    // Allow depositing without triggering the reverting fallback
    function deposit() external payable {
        (bool ok,) = address(target).call{value: msg.value}("");
        require(ok, "deposit failed");
    }
    // Fallback reverts to cause withdraw's call to fail
    fallback() external payable { revert(); }
}

