contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2) public {
        // Bound amounts to avoid overflow and keep them in the admissible domain
        amount1 = bound(amount1, 1, 1 ether);
        amount2 = bound(amount2, 1, 1 ether);
        // Prevent identical actors or reserved addresses
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != actor2);
        vm.assume(actor1 != address(this) && actor2 != address(this));
        vm.assume(actor1 != address(c) && actor2 != address(c));

        // Fund actors
        vm.deal(actor1, amount1);
        vm.deal(actor2, amount2);

        // Deposit
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: amount1}("");
        require(ok1, "deposit1 failed");
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: amount2}("");
        require(ok2, "deposit2 failed");

        // Deploy the reentrant attacker, funded with 0.5 ether of its own to call withdraw
        ReenterAttacker attacker = new ReenterAttacker(c);
        vm.deal(address(attacker), 0.5 ether);
        attacker.setTarget(actor1);

        // Attacker deposits 0.1 ether to get a balance
        vm.prank(address(attacker));
        (bool okDep, ) = address(c).call{value: 0.1 ether}("");
        require(okDep, "attacker deposit failed");

        // Capture balances before withdraw
        uint256 balActor1Before = c.balances(actor1);
        uint256 balActor2Before = c.balances(actor2);
        uint256 balAttackerBefore = c.balances(address(attacker));

        // Attacker executes withdraw
        vm.prank(address(attacker));
        attacker.attack();

        // After withdraw, read balances
        uint256 balActor1After = c.balances(actor1);
        uint256 balActor2After = c.balances(actor2);
        uint256 balAttackerAfter = c.balances(address(attacker));

        // Sum of balances decreased should equal the Ether that left the contract
        // Ether that left = initial contract balance - current contract balance
        // The invariant is: sum(balances) == address(c).balance (after any sequence of calls)
        // We compute sum of balances after attack and compare to c's balance
        uint256 totalBalAfter = balActor1After + balActor2After + balAttackerAfter;
        uint256 totalBalBefore = balActor1Before + balActor2Before + balAttackerBefore;
        uint256 contractBalAfter = address(c).balance;

        // Invariant: sum(balances) == address(c).balance
        // Correct contract always maintains this; buggy contract violates when reentrancy drains extra.
        assertTrue(totalBalAfter == contractBalAfter);
    }
}

contract ReenterAttacker {
    C public targetC;
    address public victim;

    constructor(C _c) {
        targetC = _c;
    }

    function setTarget(address _victim) external {
        victim = _victim;
    }

    function attack() external {
        // Call withdraw; during the external call, the fallback will re-enter
        targetC.withdraw();
    }

    fallback() external payable {
        // Re-enter if the victim still has balance
        if (address(targetC).balance >= targetC.balances(victim) && targetC.balances(victim) > 0) {
            targetC.withdraw();
        }
    }
}

