pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        // Deposit ether so the test contract has a balance in C
        vm.deal(address(this), amount);
        // First deposit: send ether to c
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "deposit failed");
        // First withdraw should succeed
        c.withdraw();
        // Second deposit to test if subsequent withdraw is possible
        vm.deal(address(this), amount);
        vm.prank(address(this));
        sent = false;
        (sent, ) = address(c).call{value: amount}("");
        require(sent, "second deposit failed");
        // Second withdraw: try/catch to check if it succeeds
        bool ok = true;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the second withdraw always succeeds on reference (mutant will revert)
        assertTrue(ok);
    }
}

