pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != actor2);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 <= address(this).balance && amount2 <= address(this).balance);

        // Fund both actors
        vm.deal(actor1, amount1);
        vm.deal(actor2, amount2);

        // Deposit for both actors
        vm.prank(actor1);
        (bool ok1,) = address(c).call{value: amount1}("");
        require(ok1, "deposit1 failed");
        vm.prank(actor2);
        (bool ok2,) = address(c).call{value: amount2}("");
        require(ok2, "deposit2 failed");

        // First withdraw by actor1
        vm.prank(actor1);
        bool firstOk = true;
        try c.withdraw() { firstOk = true; } catch { firstOk = false; }
        require(firstOk, "first withdraw failed");

        // Second withdraw by actor2
        vm.prank(actor2);
        bool secondOk = true;
        try c.withdraw() { secondOk = true; } catch { secondOk = false; }

        // After second withdraw attempt, check if modifier lock is released (false).
        // In reference, lock should be false; in mutant, lock remains true after first withdraw,
        // causing second withdraw to revert and lock to stay true.
        // We observe this via the public getter for __lock_modifier0_lock (auto-generated).
        assertTrue(!c.__lock_modifier0_lock() || !secondOk);
    }
}

