pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address addr) public {
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(addr != address(0) && addr != address(c) && addr != address(this));
        // make two deposits
        vm.deal(addr, amount1 + amount2);
        vm.prank(addr);
        payable(address(c)).call{value: amount1}("");
        vm.prank(addr);
        payable(address(c)).call{value: amount2}("");

        // first withdraw
        vm.prank(addr);
        c.withdraw();

        // second withdraw must succeed; bug reverts because lock not released
        vm.prank(addr);
        c.withdraw();
        assertTrue(c.balances(addr) == 0);
    }
}
